WFJ.Data.add("gossip", {
  ["7004f61a9980d187"] = { "Ho un sacco di rabbia e ostilità represse. Dammi solo un motivo, pezzente.", "." },
  ["7008516b8b67a67a"] = { "Salute, {class}. Mi occupo degli encomi per conto di ⟦Stormwind=Roccavento⟧. È mio dovere assistere gli avventurieri che hanno ricevuto un Anello d'Encomio dell'⟦Alliance=Alleanza⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne un gruppo di dieci alla volta. Quando consegnerai gli anelli, registrerò le tue gesta nei nostri archivi. Così otterrai il riconoscimento di ⟦Stormwind=Roccavento⟧ per il tuo impegno e il tuo servizio.", "." },
  ["700d37b786a4d43c"] = { "Nessuna contadina può resistere ai Defias!", "." },
  ["702067fce7f05e4d"] = { "Non troverai kebab di ratto migliore da questa parte di Khaz Modan!", "." },
  ["7023d96b8aeeee06"] = { "Ti do il benvenuto: dai pure un'occhiata alla mia merce. A parte l'odore di muffa, è in perfette condizioni.", "." },
  ["702c1efa18126341"] = { "Il suo luogotenente, Ilkrud Magthrull, possiede un tomo che potrebbe indicare dove si trovano le gemme dell'anima rimanenti.", "." },
  ["703258a6fb414410"] = { "Ah! Buongiorno, buongiorno, <maestro/maestra> {class}! Vieni, siediti e bevi qualcosa. Hai lo sguardo di chi ha spirito d'iniziativa, e credo che parlare con me varrà il tuo tempo...", "." },
  ["7033c496d8c1c374"] = { "Istruttore d'armi", "." },
  ["703c7cabc54dc8d8"] = { "Uh... la malattia è potente. E attacca la mente...", "." },
  ["704135b0b52d4a0b"] = { "Il dottor Erbanera ti darà altre istruzioni, {name}. Grazie mille per il tuo aiuto!", "." },
  ["70440afb06655c64"] = { "Sono Augustus! Se lo vuoi, ce l'ho! Se vuoi venderlo, allora lo voglio io!", "." },
  ["704a089f7f482d2e"] = { "La Fratellanza trionferà!", "." },
  ["70516ee8a7796347"] = { "Questo non era previsto. L'essere che lo ha incantato mi è noto...", "." },
  ["7056536daf6369ee"] = { "Sei tornat<o/a> di nuovo, eh? Davvero non potrei desiderare altro, ora, che un altro po' della pietà di Tor'gan.\n\nCosa mi porti stavolta? Forse un pezzo di spago dai colori vivaci? O un tratto di corda per porre fine a questa mia miseria...", "." },
  ["705c13c4629487a3"] = { "Sei già <tornato/tornata>! Cosa posso fare per te stavolta?", "." },
  ["705da94e11e2095b"] = { "Guarda dove metti i piedi qui dentro, <ragazzo/ragazza>. Il padrone vede tutto...", "." },
  ["707a451e93b91897"] = { "Per il Rosso!", "." },
  ["707e6c157f87b98d"] = { "L'altare risplende! Ce l'abbiamo fatta!", "." },
  ["707f7fd2c89d93a1"] = { "È un mestiere pericoloso, questo!\n\nMiran è appena partito per una consegna. Dovrebbe tornare tra pochi minuti.", "." },
  ["7080001b8cb18849"] = { "%s ha lanciato un potenziamento!", "." },
  ["708bbaa27d500317"] = { "Non dovrebbe volerci molto...", "." },
  ["708c9499b09886d3"] = { "Svegliatevi, servitori! Difendete i Dischi!", "." },
  ["708f69e94dee615e"] = { "La Torre Est dei Lupi Bianchi è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ la distruggerà!", "." },
  ["709381f6effcba34"] = { "Grazie, {name}. Se non fossi <arrivato/arrivata> tu, di sicuro saremmo già carne morta! Ora tra noi e il capo dei troll c'è solo quella porta laggiù...", "." },
  ["7095a5a5d1f39bb7"] = { "Gli oggetti che hai offerto erano puri, {name}. Questo nuovo totem purificatore è potente.", "." },
  ["7096afdac5f75fb2"] = { "L'ultima volta che ho avuto notizie, l'anziana Cantastella era al Tempio di Atal'Hakkar, nella ⟦Swamp of Sorrows=Palude del Dolore⟧.", "." },
  ["709ee4a5c83e197f"] = { "No, no, ti servirà MOLTO più addestramento prima di essere <pronto/pronta> a imparare da me! Va' a parlare con quel dilettante impettito di Malcomb Wynn. È quello sepolto tra i libri laggiù.", "." },
  ["70a65c2de65ba21c"] = { "%s emette un profondo sospiro.", "." },
